#!/usr/bin/env node
/**
 * Contentful Studio Experiences component definition codegen.
 *
 * Source of truth: @cf JSDoc tags on Props types in experiences/*.tsx
 *
 * Usage:
 *   npm run generate:contentful          — write definitions.ts
 *   npm run generate:contentful:check    — diff only; exits non-zero if stale
 *
 * Author conventions (see .docs/temp/contentfulCodegen.md for full spec):
 *   /** @cf-register *\/  — on the default export to opt a file in
 *   /** @cf Headline *\/  — required on every non-handler, non-children prop
 *   /** @cf Body, longText *\/  — with explicit control override
 *   /** @cf skip *\/      — explicitly exclude a prop
 *
 * Valid controls: shortText | longText | select | toggle | number | media
 * Auto-inferred: string→shortText, boolean→toggle, number→number,
 *                string-literal union→select
 * Auto-skipped:  on* handler props, children (emits children:true instead)
 * Fails loudly:  any untagged non-handler, non-children prop
 */

import { Project, SyntaxKind } from 'ts-morph';
import { readdirSync, writeFileSync, readFileSync, mkdtempSync } from 'fs';
import { join, basename, dirname } from 'path';
import { fileURLToPath } from 'url';
import { tmpdir } from 'os';
import { execSync } from 'child_process';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const ROOT = join(__dirname, '../../');
const EXPERIENCES_DIR =
  process.env.CF_EXPERIENCES_DIR ||
  join(ROOT, 'overrides/app/components/contentful/experiences');
const OUTPUT_FILE = join(EXPERIENCES_DIR, 'definitions.ts');
const TSCONFIG = join(ROOT, 'tsconfig.json');

const CHECK_MODE = process.argv.includes('--check');

// Contentful variable shape keyed by @cf control name
const CONTROL_MAP = {
  shortText: { type: 'Text', defaultValue: '' },
  longText: { type: 'Text', defaultValue: '' },

